    | where TimeGenerated between (StartTimestamp .. EndTimestamp)
    | where RecipientEmailAddress =~ ValueMail or SenderFromAddress =~ ValueMail or SenderMailFromAddress =~ ValueMail
    | summarize MailTime = min(TimeGenerated), Subject = take_any(Subject), Sender = take_any(SenderFromAddress) by NetworkMessageId;
let Clicks = UrlClickEvents
    | where TimeGenerated between (StartTimestamp .. now())
    | summarize Clicks = count(), Clickers = make_set(AccountUpn, 10) by NetworkMessageId, Url;
union isfuzzy=true
(
    EmailUrlInfo
    | where TimeGenerated between (StartTimestamp .. EndTimestamp)
    | join kind=inner (Msgs) on NetworkMessageId
    | join kind=leftouter (Clicks) on NetworkMessageId, Url
    | project MailTime, Sender, Subject, Kind = "URL", Item = Url, Info = strcat(UrlDomain, " · ", UrlLocation),
        SHA256 = "", Threat = "", Clicks = coalesce(Clicks, 0), Clickers, NetworkMessageId
),
(
    EmailAttachmentInfo
    | where TimeGenerated between (StartTimestamp .. EndTimestamp)
    | join kind=inner (Msgs) on NetworkMessageId
    | project MailTime, Sender, Subject, Kind = "Pièce jointe", Item = FileName, Info = strcat(FileType, " · ", tostring(FileSize), " octets"),
        SHA256, Threat = strcat(ThreatTypes, " ", ThreatNames), Clicks = long(null), Clickers = dynamic(null), NetworkMessageId
)
